\set ON_ERROR_STOP on
BEGIN;
DO $vedu_ktlt_22$
DECLARE
  v_course bigint;
  v_count integer;
  rec record;
  item jsonb;
  expected jsonb := $json$[{"order": 1, "title": "Phong cách lập trình, ngoại lệ và tập tin", "addition": "\n\n[VEDU-KTLT-PRACTICE-V1]\nBÀI THỰC HÀNH TỰ NGUYỆN 01 — Đọc dữ liệu và xử lý lỗi tệp\nYêu cầu: Viết chương trình C++ đọc danh sách số nguyên từ numbers.txt, tính tổng và xuất kết quả ra result.txt. Kiểm tra lỗi mở file, dòng không phải số và file rỗng. Dùng hàm riêng để đọc, xử lý và ghi kết quả.\n\nCA KIỂM THỬ: File không tồn tại; file rỗng; 5 số hợp lệ; dòng có chữ; giá trị âm.\n\nTIÊU CHÍ ĐÁNH GIÁ (10 ĐIỂM): Đúng chức năng 4; xử lý đầu vào và biên 2; kiểm thử 2; giải thích thuật toán và trình bày 2.\nBài thực hành chỉ để luyện tập, không quyết định việc mở bài tiếp theo; học viên cần đạt quiz của bài học theo quy định.\nĐề thực hành VEDU biên soạn theo chủ đề khóa học."}, {"order": 2, "title": "Mảng một chiều: tổng, đếm, tìm kiếm, min/max", "addition": "\n\n[VEDU-KTLT-PRACTICE-V1]\nBÀI THỰC HÀNH TỰ NGUYỆN 02 — Thống kê mảng một chiều\nYêu cầu: Nhập n và n số nguyên (n từ 1 đến 1000). Tính tổng, đếm số chẵn, tìm giá trị nhỏ nhất/lớn nhất và vị trí xuất hiện đầu tiên. Cài đặt tìm tuyến tính một giá trị x.\n\nCA KIỂM THỬ: n=1; số âm; toàn số trùng; x không tồn tại; n ngoài giới hạn.\n\nTIÊU CHÍ ĐÁNH GIÁ (10 ĐIỂM): Đúng chức năng 4; xử lý đầu vào và biên 2; kiểm thử 2; giải thích thuật toán và trình bày 2.\nBài thực hành chỉ để luyện tập, không quyết định việc mở bài tiếp theo; học viên cần đạt quiz của bài học theo quy định.\nĐề thực hành VEDU biên soạn theo chủ đề khóa học."}, {"order": 3, "title": "Sắp xếp, thêm và xóa phần tử", "addition": "\n\n[VEDU-KTLT-PRACTICE-V1]\nBÀI THỰC HÀNH TỰ NGUYỆN 03 — Chèn, xóa và sắp xếp mảng\nYêu cầu: Cài đặt chèn một phần tử vào vị trí k, xóa phần tử ở vị trí k và sắp xếp tăng dần bằng insertion sort. In mảng trước/sau mỗi thao tác và phân tích số lần dịch phần tử.\n\nCA KIỂM THỬ: Mảng rỗng; chèn đầu/cuối; vị trí sai; đã tăng dần; mảng đảo ngược.\n\nTIÊU CHÍ ĐÁNH GIÁ (10 ĐIỂM): Đúng chức năng 4; xử lý đầu vào và biên 2; kiểm thử 2; giải thích thuật toán và trình bày 2.\nBài thực hành chỉ để luyện tập, không quyết định việc mở bài tiếp theo; học viên cần đạt quiz của bài học theo quy định.\nĐề thực hành VEDU biên soạn theo chủ đề khóa học."}, {"order": 4, "title": "Mảng hai chiều và ma trận", "addition": "\n\n[VEDU-KTLT-PRACTICE-V1]\nBÀI THỰC HÀNH TỰ NGUYỆN 04 — Xử lý ma trận hai chiều\nYêu cầu: Đọc ma trận m×n số nguyên. Tính tổng từng hàng/cột, tìm phần tử lớn nhất; nếu m=n, tính tổng đường chéo chính và phụ (không đếm giao điểm hai lần khi cộng tổng hai đường chéo).\n\nCA KIỂM THỬ: Ma trận 1×1; 2×3; 3×3; số âm; không phải ma trận vuông.\n\nTIÊU CHÍ ĐÁNH GIÁ (10 ĐIỂM): Đúng chức năng 4; xử lý đầu vào và biên 2; kiểm thử 2; giải thích thuật toán và trình bày 2.\nBài thực hành chỉ để luyện tập, không quyết định việc mở bài tiếp theo; học viên cần đạt quiz của bài học theo quy định.\nĐề thực hành VEDU biên soạn theo chủ đề khóa học."}, {"order": 5, "title": "Chuỗi cơ bản, chuẩn hóa và token", "addition": "\n\n[VEDU-KTLT-PRACTICE-V1]\nBÀI THỰC HÀNH TỰ NGUYỆN 05 — Chuẩn hóa chuỗi và tách từ\nYêu cầu: Viết chương trình C++ chuẩn hóa chuỗi ASCII: xóa khoảng trắng ở đầu/cuối, thay nhiều khoảng trắng liên tiếp bằng một dấu cách; tách các từ và in số lượng từ. Nêu rõ giới hạn với Unicode UTF-8.\n\nCA KIỂM THỬ: Chuỗi rỗng; toàn khoảng trắng; một từ; nhiều khoảng trắng; câu có dấu câu.\n\nTIÊU CHÍ ĐÁNH GIÁ (10 ĐIỂM): Đúng chức năng 4; xử lý đầu vào và biên 2; kiểm thử 2; giải thích thuật toán và trình bày 2.\nBài thực hành chỉ để luyện tập, không quyết định việc mở bài tiếp theo; học viên cần đạt quiz của bài học theo quy định.\nĐề thực hành VEDU biên soạn theo chủ đề khóa học."}, {"order": 6, "title": "Tìm kiếm, đếm và thay thế chuỗi con", "addition": "\n\n[VEDU-KTLT-PRACTICE-V1]\nBÀI THỰC HÀNH TỰ NGUYỆN 06 — Tìm và thay thế chuỗi con\nYêu cầu: Viết hai hàm: đếm số lần xuất hiện chuỗi con (cho phép chồng lấn); thay thế tất cả lần xuất hiện không chồng lấn bằng chuỗi mới (duyệt trên chuỗi gốc). Không cho phép mẫu tìm kiếm rỗng.\n\nCA KIỂM THỬ: aaaa tìm aa (đếm=3); chuỗi không chứa mẫu; mẫu dài hơn chuỗi; thay thế thành chuỗi rỗng; mẫu rỗng.\n\nTIÊU CHÍ ĐÁNH GIÁ (10 ĐIỂM): Đúng chức năng 4; xử lý đầu vào và biên 2; kiểm thử 2; giải thích thuật toán và trình bày 2.\nBài thực hành chỉ để luyện tập, không quyết định việc mở bài tiếp theo; học viên cần đạt quiz của bài học theo quy định.\nĐề thực hành VEDU biên soạn theo chủ đề khóa học."}, {"order": 7, "title": "Đệ quy tuyến tính và nhị phân", "addition": "\n\n[VEDU-KTLT-PRACTICE-V1]\nBÀI THỰC HÀNH TỰ NGUYỆN 07 — Cài đặt và so sánh đệ quy\nYêu cầu: Viết hàm giai thừa đệ quy, tính Fibonacci bằng đệ quy trực tiếp và bằng vòng lặp. Nêu trường hợp cơ sở, phân tích số lời gọi và so sánh khi n tăng. Giới hạn n để tránh tràn số/ngăn xếp.\n\nCA KIỂM THỬ: n=0; n=1; n=5; n âm; n quá lớn; kết quả đệ quy so với vòng lặp.\n\nTIÊU CHÍ ĐÁNH GIÁ (10 ĐIỂM): Đúng chức năng 4; xử lý đầu vào và biên 2; kiểm thử 2; giải thích thuật toán và trình bày 2.\nBài thực hành chỉ để luyện tập, không quyết định việc mở bài tiếp theo; học viên cần đạt quiz của bài học theo quy định.\nĐề thực hành VEDU biên soạn theo chủ đề khóa học."}, {"order": 8, "title": "Đệ quy lồng, hỗ tương và ứng dụng", "addition": "\n\n[VEDU-KTLT-PRACTICE-V1]\nBÀI THỰC HÀNH TỰ NGUYỆN 08 — Đệ quy hỗ tương và đệ quy lồng\nYêu cầu: Cài đặt hai hàm isEven(n)/isOdd(n) gọi hỗ tương với n nguyên không âm. Cài thêm McCarthy 91 M(n) theo M(n)=n-10 khi n>100, M(M(n+11)) khi n≤100; đếm số lời gọi và giải thích điểm dừng cho các đầu vào đã kiểm thử.\n\nCA KIỂM THỬ: isEven/isOdd với 0,1,10; M(50)=91; M(100)=91; M(101)=91; kiểm soát n âm cho hàm chẵn/lẻ.\n\nTIÊU CHÍ ĐÁNH GIÁ (10 ĐIỂM): Đúng chức năng 4; xử lý đầu vào và biên 2; kiểm thử 2; giải thích thuật toán và trình bày 2.\nBài thực hành chỉ để luyện tập, không quyết định việc mở bài tiếp theo; học viên cần đạt quiz của bài học theo quy định.\nĐề thực hành VEDU biên soạn theo chủ đề khóa học."}]$json$::jsonb;
BEGIN
  SELECT course_id INTO v_course FROM lms.curated_courses WHERE course_key='programming-techniques';
  IF v_course IS NULL THEN RAISE EXCEPTION 'Missing programming-techniques course'; END IF;
  SELECT count(*) INTO v_count FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
   WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted;
  IF v_count<>8 THEN RAISE EXCEPTION 'Expected 8 lessons; got %',v_count; END IF;
  FOR rec IN SELECT l.lesson_id,l.title,l.content,row_number() OVER(ORDER BY l.lesson_order,l.lesson_id) AS rn
     FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
     WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted
     ORDER BY l.lesson_order,l.lesson_id
  LOOP
    item := expected->(rec.rn::int-1);
    IF item IS NULL OR regexp_replace(rec.title,'^\s*[0-9]{1,2}\s*[·.:-]\s*','','g') <> item->>'title' THEN
      RAISE EXCEPTION 'Lesson % mismatch: %',rec.rn,rec.title;
    END IF;
  END LOOP;
  FOR rec IN SELECT l.lesson_id,l.title,l.content,row_number() OVER(ORDER BY l.lesson_order,l.lesson_id) AS rn
     FROM lms.lessons l JOIN lms.course_sections s ON s.section_id=l.section_id
     WHERE l.course_id=v_course AND s.module_key<>'intro' AND l.is_published AND NOT l.is_deleted
     ORDER BY l.lesson_order,l.lesson_id
  LOOP
    item := expected->(rec.rn::int-1);
    IF position('[VEDU-KTLT-PRACTICE-V1]' in coalesce(rec.content,''))=0 THEN
      UPDATE lms.lessons SET content=coalesce(content,'') || (item->>'addition'),updated_at=now() WHERE lesson_id=rec.lesson_id;
    END IF;
  END LOOP;
END $vedu_ktlt_22$;
COMMIT;
